-- Replace the seeded placeholder descriptions on the 51 Palms Off Gaming rows
-- with the per-product copy now in data/palmsOffProductCopy.js.
--
-- The seed (20260825023045) wrote "<title>. <product type blurb>" for every
-- row, which meant every top loader shared one description and every sleeve
-- shared another. The product pages themselves render from the data module, so
-- this is about the places that read the column instead: /admin/products, the
-- shop grid, and the generic /product/shop/<id> renderer.
--
-- Guarded on the seeded value: a row whose description has been edited in the
-- admin since seeding is left alone. That makes this safe to re-run and safe
-- to land after someone has started editing copy by hand.

update public.shop_products p
set description = v.new_description,
    updated_at = now()
from (values
  ('palms-off-gaming-blackout-deck-sleeves-japanese-mini-size', 'Palms Off Gaming Blackout Deck Sleeves — Japanese Mini Size. Blackout deck sleeves and premium over sleeves in standard and Japanese mini sizes.', 'Blackout deck sleeves in Japanese mini size from Palms Off Gaming — opaque backs, 14 colours. Sized for Japanese Pokémon and Yu-Gi-Oh cards.'),
  ('palms-off-gaming-blackout-deck-sleeves-japanese-mini-size-matte', 'Palms Off Gaming Blackout Deck Sleeves — Japanese Mini Size, Matte. Blackout deck sleeves and premium over sleeves in standard and Japanese mini sizes.', 'Matte blackout deck sleeves in Japanese mini size from Palms Off Gaming — opaque backs, reduced glare, 14 colours. For Japanese Pokémon and Yu-Gi-Oh.'),
  ('palms-off-gaming-blackout-deck-sleeves-standard-size', 'Palms Off Gaming Blackout Deck Sleeves — Standard Size. Blackout deck sleeves and premium over sleeves in standard and Japanese mini sizes.', 'Blackout deck sleeves in standard size from Palms Off Gaming — opaque backs, 14 colours. For Pokémon, Magic, One Piece, Lorcana and sports cards.'),
  ('palms-off-gaming-blackout-deck-sleeves-standard-size-matte', 'Palms Off Gaming Blackout Deck Sleeves — Standard Size, Matte. Blackout deck sleeves and premium over sleeves in standard and Japanese mini sizes.', 'Matte blackout deck sleeves in standard size from Palms Off Gaming — opaque backs, reduced glare, 14 colours. For Pokémon, Magic, One Piece and sports cards.'),
  ('palms-off-gaming-premium-over-sleeves-japanese-mini-clear', 'Palms Off Gaming Premium Over Sleeves — Japanese Mini, Clear. Blackout deck sleeves and premium over sleeves in standard and Japanese mini sizes.', 'Clear premium over sleeves in Japanese mini size from Palms Off Gaming — the outer half of a double-sleeve for Japanese Pokémon and Yu-Gi-Oh.'),
  ('palms-off-gaming-premium-over-sleeves-japanese-mini-matte', 'Palms Off Gaming Premium Over Sleeves — Japanese Mini, Matte. Blackout deck sleeves and premium over sleeves in standard and Japanese mini sizes.', 'Matte premium over sleeves in Japanese mini size from Palms Off Gaming — glare-free outer sleeves for double-sleeved Japanese Pokémon and Yu-Gi-Oh.'),
  ('palms-off-gaming-premium-over-sleeves-standard-clear', 'Palms Off Gaming Premium Over Sleeves — Standard, Clear. Blackout deck sleeves and premium over sleeves in standard and Japanese mini sizes.', 'Clear premium over sleeves in standard size from Palms Off Gaming — the outer half of a double-sleeve, so the inner sleeve is never handled.'),
  ('palms-off-gaming-premium-over-sleeves-standard-matte', 'Palms Off Gaming Premium Over Sleeves — Standard, Matte. Blackout deck sleeves and premium over sleeves in standard and Japanese mini sizes.', 'Matte premium over sleeves in standard size from Palms Off Gaming — the outer half of a double-sleeve, with a glare-free finish.'),
  ('palms-off-gaming-card-loaders-100pt', 'Palms Off Gaming Card Loaders 100pt. Rigid top loaders and card loaders from 35pt to 180pt, plus a booster pack size.', '100pt card loaders from Palms Off Gaming — rigid protection for heavy patch and relic cards.'),
  ('palms-off-gaming-card-loaders-180pt', 'Palms Off Gaming Card Loaders 180pt. Rigid top loaders and card loaders from 35pt to 180pt, plus a booster pack size.', '180pt card loaders from Palms Off Gaming — the largest point size, for the thickest booklet and memorabilia cards.'),
  ('palms-off-gaming-card-loaders-35pt', 'Palms Off Gaming Card Loaders 35pt. Rigid top loaders and card loaders from 35pt to 180pt, plus a booster pack size.', '35pt card loaders from Palms Off Gaming — rigid protection for standard modern trading cards.'),
  ('palms-off-gaming-top-loaders-100pt', 'Palms Off Gaming Top Loaders 100pt. Rigid top loaders and card loaders from 35pt to 180pt, plus a booster pack size.', '100pt rigid top loaders from Palms Off Gaming — for heavy patch and multi-piece relic cards.'),
  ('palms-off-gaming-top-loaders-130pt', 'Palms Off Gaming Top Loaders 130pt. Rigid top loaders and card loaders from 35pt to 180pt, plus a booster pack size.', '130pt rigid top loaders from Palms Off Gaming — for the thickest memorabilia and multi-swatch cards.'),
  ('palms-off-gaming-top-loaders-180pt', 'Palms Off Gaming Top Loaders 180pt. Rigid top loaders and card loaders from 35pt to 180pt, plus a booster pack size.', '180pt rigid top loaders from Palms Off Gaming — the largest point size in the range, for the thickest cards.'),
  ('palms-off-gaming-top-loaders-35pt', 'Palms Off Gaming Top Loaders 35pt. Rigid top loaders and card loaders from 35pt to 180pt, plus a booster pack size.', '35pt rigid top loaders from Palms Off Gaming — the standard size for modern trading cards. For posting, trading and everyday protection.'),
  ('palms-off-gaming-top-loaders-55pt', 'Palms Off Gaming Top Loaders 55pt. Rigid top loaders and card loaders from 35pt to 180pt, plus a booster pack size.', '55pt rigid top loaders from Palms Off Gaming — for thicker-stock cards that will not fit a standard 35pt loader.'),
  ('palms-off-gaming-top-loaders-75pt', 'Palms Off Gaming Top Loaders 75pt. Rigid top loaders and card loaders from 35pt to 180pt, plus a booster pack size.', '75pt rigid top loaders from Palms Off Gaming — for thick relic, jersey and patch cards.'),
  ('palms-off-gaming-booster-pack-top-loaders', 'Palms Off Gaming Booster Pack Top Loaders. Rigid top loaders and card loaders from 35pt to 180pt, plus a booster pack size.', 'Booster pack top loaders from Palms Off Gaming — rigid protection sized for a sealed booster pack rather than a single card.'),
  ('palms-off-gaming-command-case', 'Palms Off Gaming Command Case. Hard cases for transporting and displaying cards.', 'Palms Off Gaming Command Case — a hard case for transporting and storing cards. See the product photos for the interior layout.'),
  ('palms-off-gaming-command-case-10-pack', 'Palms Off Gaming Command Case — 10 Pack. Hard cases for transporting and displaying cards.', 'Palms Off Gaming Command Case, 10 pack — bulk quantity of the hard carry case, for stores and collectors kitting out a whole collection at once.'),
  ('palms-off-gaming-genesis-deck-box', 'Palms Off Gaming Genesis Deck Box. Genesis and Portal deck boxes for sleeved decks.', 'Genesis deck box from Palms Off Gaming — a buckle-closed deck box for sleeved decks, in seven colours.'),
  ('palms-off-gaming-portal-deck-box-nexus-100', 'Palms Off Gaming Portal Deck Box Nexus 100. Genesis and Portal deck boxes for sleeved decks.', 'Portal Deck Box Nexus 100 from Palms Off Gaming — a deck box for sleeved, playable decks, with a different closure and profile to the Genesis.'),
  ('palms-off-gaming-collectors-series-large-graded-card-case', 'Palms Off Gaming Collector''s Series Large Graded Card Case. Small, medium and large carry cases sized for graded slabs.', 'Collector''s Series large graded card case from Palms Off Gaming — the highest-capacity hard carry case for graded slabs. Five colours.'),
  ('palms-off-gaming-collectors-series-medium-graded-card-case', 'Palms Off Gaming Collector''s Series Medium Graded Card Case. Small, medium and large carry cases sized for graded slabs.', 'Collector''s Series medium graded card case from Palms Off Gaming — a hard carry case sized for graded slabs. Seven colours.'),
  ('palms-off-gaming-collectors-series-small-graded-card-case', 'Palms Off Gaming Collector''s Series Small Graded Card Case. Small, medium and large carry cases sized for graded slabs.', 'Collector''s Series small graded card case from Palms Off Gaming — a hard carry case sized for graded slabs. Seven colours.'),
  ('palms-off-gaming-semi-rigid-grading-holders-200-pack', 'Palms Off Gaming Semi-Rigid Grading Holders — 200 Pack. Semi-rigid card holders in 50 and 200 packs — the format grading companies ask for.', 'Semi-rigid grading holders from Palms Off Gaming, 200 pack — bulk submission supply for PSA, BGS, CGC and ACE.'),
  ('palms-off-gaming-semi-rigid-grading-holders-50-pack', 'Palms Off Gaming Semi-Rigid Grading Holders — 50 Pack. Semi-rigid card holders in 50 and 200 packs — the format grading companies ask for.', 'Semi-rigid grading holders from Palms Off Gaming, 50 pack — the holder PSA, BGS, CGC and ACE ask for on submission.'),
  ('palms-off-gaming-mag-lock-card-case-100pt', 'Palms Off Gaming Mag Lock Card Case 100pt. Magnetic one-touch acrylic cases from 35pt to 180pt.', '100pt mag lock card case from Palms Off Gaming — magnetic one-touch acrylic case for heavy patch and relic cards.'),
  ('palms-off-gaming-mag-lock-card-case-130pt', 'Palms Off Gaming Mag Lock Card Case 130pt. Magnetic one-touch acrylic cases from 35pt to 180pt.', '130pt mag lock card case from Palms Off Gaming — magnetic one-touch acrylic case for thick memorabilia cards.'),
  ('palms-off-gaming-mag-lock-card-case-180pt', 'Palms Off Gaming Mag Lock Card Case 180pt. Magnetic one-touch acrylic cases from 35pt to 180pt.', '180pt mag lock card case from Palms Off Gaming — the largest one-touch in the range, for the thickest cards.'),
  ('palms-off-gaming-mag-lock-card-case-35pt', 'Palms Off Gaming Mag Lock Card Case 35pt. Magnetic one-touch acrylic cases from 35pt to 180pt.', '35pt mag lock card case from Palms Off Gaming — magnetic one-touch acrylic display case for standard modern cards.'),
  ('palms-off-gaming-mag-lock-card-case-55pt', 'Palms Off Gaming Mag Lock Card Case 55pt. Magnetic one-touch acrylic cases from 35pt to 180pt.', '55pt mag lock card case from Palms Off Gaming — magnetic one-touch acrylic case for thicker-stock cards.'),
  ('palms-off-gaming-mag-lock-card-case-75pt', 'Palms Off Gaming Mag Lock Card Case 75pt. Magnetic one-touch acrylic cases from 35pt to 180pt.', '75pt mag lock card case from Palms Off Gaming — magnetic one-touch acrylic case for jersey and relic cards.'),
  ('palms-off-gaming-mint-fit-bgs-slab-sleeves-regular', 'Palms Off Gaming Mint Fit BGS Slab Sleeves — Regular. Sleeves cut to fit specific holders — PSA and BGS slabs, mag lock cases, top loaders and booster packs.', 'Mint Fit BGS slab sleeves (regular) from Palms Off Gaming — sleeves cut to fit a standard BGS graded slab.'),
  ('palms-off-gaming-mint-fit-inner-sleeves-japanese-mini-size', 'Palms Off Gaming Mint Fit Inner Sleeves — Japanese Mini Size. Snug inner sleeves in standard and Japanese mini sizes, top-loading and side-loading.', 'Mint Fit inner sleeves in Japanese mini size from Palms Off Gaming — snug inner sleeves for double-sleeving Japanese Pokémon and Yu-Gi-Oh.'),
  ('palms-off-gaming-mint-fit-inner-sleeves-standard-size', 'Palms Off Gaming Mint Fit Inner Sleeves — Standard Size. Snug inner sleeves in standard and Japanese mini sizes, top-loading and side-loading.', 'Mint Fit inner sleeves in standard size from Palms Off Gaming — snug inner sleeves for double-sleeving Pokémon, Magic and sports cards.'),
  ('palms-off-gaming-mint-fit-mag-lock-sleeves-100pt-to-130pt', 'Palms Off Gaming Mint Fit Mag Lock Sleeves — 100pt to 130pt. Sleeves cut to fit specific holders — PSA and BGS slabs, mag lock cases, top loaders and booster packs.', 'Mint Fit mag lock sleeves for 100pt to 130pt cases from Palms Off Gaming — sleeves for the larger one-touch sizes.'),
  ('palms-off-gaming-mint-fit-mag-lock-sleeves-35pt-to-75pt', 'Palms Off Gaming Mint Fit Mag Lock Sleeves — 35pt to 75pt. Sleeves cut to fit specific holders — PSA and BGS slabs, mag lock cases, top loaders and booster packs.', 'Mint Fit mag lock sleeves for 35pt to 75pt cases from Palms Off Gaming — sleeves that protect the one-touch itself.'),
  ('palms-off-gaming-mint-fit-booster-pack-sleeves-extra-thick', 'Palms Off Gaming Mint Fit Booster Pack Sleeves — Extra Thick. Sleeves cut to fit specific holders — PSA and BGS slabs, mag lock cases, top loaders and booster packs.', 'Mint Fit booster pack sleeves (extra thick) from Palms Off Gaming — heavier sleeves for sealed booster packs.'),
  ('palms-off-gaming-mint-fit-psa-slab-sleeves-extra-thick', 'Palms Off Gaming Mint Fit PSA Slab Sleeves — Extra Thick. Sleeves cut to fit specific holders — PSA and BGS slabs, mag lock cases, top loaders and booster packs.', 'Mint Fit PSA slab sleeves (extra thick) from Palms Off Gaming — sleeves for the deeper PSA slabs that a regular sleeve will not fit.'),
  ('palms-off-gaming-mint-fit-psa-slab-sleeves-regular', 'Palms Off Gaming Mint Fit PSA Slab Sleeves — Regular. Sleeves cut to fit specific holders — PSA and BGS slabs, mag lock cases, top loaders and booster packs.', 'Mint Fit PSA slab sleeves (regular) from Palms Off Gaming — sleeves cut to fit a standard PSA graded slab.'),
  ('palms-off-gaming-mint-fit-side-loading-inner-sleeves-japanese-mini-size', 'Palms Off Gaming Mint Fit Side-Loading Inner Sleeves — Japanese Mini Size. Snug inner sleeves in standard and Japanese mini sizes, top-loading and side-loading.', 'Mint Fit side-loading inner sleeves in Japanese mini size from Palms Off Gaming — right-angle sealing for Japanese Pokémon and Yu-Gi-Oh.'),
  ('palms-off-gaming-mint-fit-side-loading-inner-sleeves-standard-size', 'Palms Off Gaming Mint Fit Side-Loading Inner Sleeves — Standard Size. Snug inner sleeves in standard and Japanese mini sizes, top-loading and side-loading.', 'Mint Fit side-loading inner sleeves in standard size from Palms Off Gaming — the opening sits at right angles to the outer sleeve.'),
  ('palms-off-gaming-mint-fit-top-loader-sleeves-35pt', 'Palms Off Gaming Mint Fit Top Loader Sleeves — 35pt. Sleeves cut to fit specific holders — PSA and BGS slabs, mag lock cases, top loaders and booster packs.', 'Mint Fit top loader sleeves (35pt) from Palms Off Gaming — sleeves cut to fit a standard 35pt top loader.'),
  ('palms-off-gaming-mint-fit-booster-pack-top-loader-sleeves', 'Palms Off Gaming Mint Fit Booster Pack Top Loader Sleeves. Sleeves cut to fit specific holders — PSA and BGS slabs, mag lock cases, top loaders and booster packs.', 'Mint Fit booster pack top loader sleeves from Palms Off Gaming — sleeves sized for a booster pack top loader.'),
  ('palms-off-gaming-playmat', 'Palms Off Gaming Playmat. Rubber-backed playmats in eight colours.', 'Palms Off Gaming playmat — rubber-backed mat for play, trading and card photography. Available in eight colours.'),
  ('palms-off-gaming-serialised-tamper-seals', 'Palms Off Gaming Serialised Tamper Seals. Numbered tamper-evident seals for sealed product and consignment.', 'Palms Off Gaming serialised tamper seals — numbered, tamper-evident seals on a roll for sealed product, breaks and consignment.'),
  ('palms-off-gaming-soft-card-sleeves-japanese-mini-size', 'Palms Off Gaming Soft Card Sleeves — Japanese Mini Size. Penny sleeves in standard and Japanese mini sizes.', 'Soft card sleeves in Japanese mini size from Palms Off Gaming — first-layer protection for Japanese Pokémon and Yu-Gi-Oh cards.'),
  ('palms-off-gaming-soft-card-sleeves-standard-size', 'Palms Off Gaming Soft Card Sleeves — Standard Size. Penny sleeves in standard and Japanese mini sizes.', 'Soft card sleeves in standard size from Palms Off Gaming — the first layer of protection for Pokémon, Magic, One Piece and sports cards.'),
  ('palms-off-gaming-tag-sleeves', 'Palms Off Gaming Tag Sleeves. Sleeves for labelling and tagging cards in inventory.', 'Palms Off Gaming tag sleeves — sleeves that hold a price or inventory tag alongside the card, with nothing adhesive touching it.'),
  ('palms-off-gaming-team-bags', 'Palms Off Gaming Team Bags. Resealable bags sized for a card in a top loader.', 'Palms Off Gaming team bags — resealable outer bags sized to fit a card already in a top loader.')
) as v(slug, seeded_description, new_description)
where p.slug = v.slug
  and p.brand = 'Palms Off Gaming'
  and p.description = v.seeded_description;
